<script setup>
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { storeToRefs } from 'pinia'
import { useI18n } from 'vue-i18n'
import AppLoading from './components/AppLoading.vue'
import AppToast from './components/AppToast.vue'
import CharacterSelectModal from './components/CharacterSelectModal.vue'
import LanguageMenu from './components/LanguageMenu.vue'
import RewardHistoryModal from './components/RewardHistoryModal.vue'
import SpinResultModal from './components/SpinResultModal.vue'
import TicketHistoryModal from './components/TicketHistoryModal.vue'
import WinHistoryModal from './components/WinHistoryModal.vue'
import { useCheckinCarousel } from './composables/useCheckinCarousel'
import { useCheckinActions } from './composables/useCheckinActions'
import { useGlobalActions } from './composables/useGlobalActions'
import { useSectionNav } from './composables/useSectionNav'
import { useTopupActions } from './composables/useTopupActions'
import { useUtc5Clock } from './composables/useUtc5Clock'
import { useWheelActions } from './composables/useWheelActions'
import { LANGUAGE_OPTIONS, persistLocale } from './i18n'
import { useActivityStore } from './stores/activity'
import { useUserStore } from './stores/user'
import { ExternalLinks, openExternalLink } from './utils/links'
import wheelDiscImg from './assets/images/wheel-disc.png'
import wheelStandImg from './assets/images/wheel-stand.png'
import wheelFrameImg from './assets/images/wheel-frame.png'
import wheelCharacterImg from './assets/images/wheel-character.png'
import { isInGameKitWebView, resolveLoginToken } from './bridge/auth.js'
import { fetchSdkGameRole } from './bridge/role.js'


async function trySelectRoleFromSdk() {
  try {
    const sdkRole = await fetchSdkGameRole()
    if (!sdkRole?.roleId) return

    await userStore.selectRole(sdkRole.roleId)
  } catch (e) {
    console.warn('[SDK] auto select role failed', e)
    // 失败则仍走手动选角
  }
}

const { t, tm, locale } = useI18n()

const wheelProbabilityLeft = computed(() => {
  const lines = tm('wheel.probabilityLeft')
  return Array.isArray(lines) ? lines : []
})

const wheelProbabilityRight = computed(() => {
  const lines = tm('wheel.probabilityRight')
  return Array.isArray(lines) ? lines : []
})

const {
  handleLoginClick,
  handleDownloadClick,
  handleFacebookClick,
  handleDiscordClick,
} = useGlobalActions()

const {
  checkedDays,
  progressBarStyle,
  dailyCheckinButtonClass,
  milestone7Class,
  milestone10Class,
  getDayClass,
  refreshCheckinStatus,
  handleDailyCheckin,
  handleDayClick,
  handleMilestoneClaim,
  handleRewardHistoryClick,
} = useCheckinActions()

const {
  tickets,
  wheelRotation,
  isWheelSpinning,
  rotatorRef,
  refreshWheelInfo,
  handleSpinX1,
  handleSpinX10,
  handleTicketHistoryClick,
  handleWinHistoryClick,
} = useWheelActions()

const wheelIconStyle = computed(() => ({
  transform: `rotate(${wheelRotation.value}deg)`,
}))

const { currentUtc5Text, syncServerOffset } = useUtc5Clock()
const { carouselImageStyle, showPrev: showCarouselPrev, showNext: showCarouselNext } = useCheckinCarousel()

const {
  totalTopup,
  topupProgressBarStyle,
  getTierClass: getTopupTierClass,
  refreshTopupProgress,
  handleTierClaim: handleTopupTierClaim,
  handleTopupCenterClick,
} = useTopupActions()

const activityStore = useActivityStore()
const userStore = useUserStore()
const { eventDurationText } = storeToRefs(activityStore)

const languageMenuVisible = ref(false)
const languageOptions = LANGUAGE_OPTIONS
const currentLanguageLabel = computed(
  () => languageOptions.find((item) => item.code === locale.value)?.label ?? 'English',
)

function toggleLanguageMenu() {
  languageMenuVisible.value = !languageMenuVisible.value
}

/** @param {string} code */
function selectLanguage(code) {
  locale.value = code
  persistLocale(code)
  languageMenuVisible.value = false
}

function openFooterLink(type) {
  if (type === 'privacy') openExternalLink(ExternalLinks.PRIVACY)
  if (type === 'terms') openExternalLink(ExternalLinks.TERMS)
}

watch(
  () => userStore.canParticipate,
  (canParticipate) => {
    if (canParticipate) {
      refreshCheckinStatus()
      refreshWheelInfo()
      refreshTopupProgress()
    }
  },
  { immediate: true },
)

watch(
  () => userStore.role?.roleId,
  (roleId, prevRoleId) => {
    if (roleId && roleId !== prevRoleId && userStore.canParticipate) {
      refreshCheckinStatus()
      refreshWheelInfo()
      refreshTopupProgress()
    }
  },
)

const DESIGN_WIDTH = 1920
const DESIGN_HEIGHT = 8318
const MOBILE_MAX_WIDTH = 768
const scale = ref(1)

const { scrollToSection, scrollToTop, getTabClass: getNavTabClass } = useSectionNav(scale)

function updateScale() {
  const w = window.visualViewport?.width ?? window.innerWidth
  if (w <= MOBILE_MAX_WIDTH) {
    scale.value = w / DESIGN_WIDTH
    return
  }
  scale.value = Math.min(1, w / DESIGN_WIDTH)
}

//async function bootstrapAppData() {
//  try {
//    await Promise.all([
//      activityStore.loadInfo(),
//      userStore.loadSession(),
//    ])
//    syncServerOffset()
//  } catch (error) {
//    console.error('[bootstrap] failed to load initial data', error)
//  }
//}
async function bootstrapAppData() {
  try {
    // 自动登录：WebView 用 SDK token，浏览器用 URL player_token / env token / localStorage
    if (!userStore.isLoggedIn) {
      try {
        const token = await resolveLoginToken()
        if (token) {
          await userStore.login({ accessToken: token })
        }
      } catch (e) {
        console.warn('[auto-login] failed', e)
      }
    }

    await Promise.all([
      activityStore.loadInfo(),
      userStore.loadSession(),
    ])
    syncServerOffset()

    if (isInGameKitWebView() && userStore.isLoggedIn && !userStore.hasRole) {
      await trySelectRoleFromSdk()
    }
  } catch (error) {
    console.error('[bootstrap] failed to load initial data', error)
  }
}

const viewportStyle = computed(() => ({
  height: `${DESIGN_HEIGHT * scale.value}px`,
}))

const canvasStyle = computed(() => ({
  transform: `scale(${scale.value})`,
}))

const fixedNavHostStyle = computed(() => ({
  transform: `translateY(-50%) scale(${scale.value})`,
}))

onMounted(() => {
  updateScale()
  bootstrapAppData()
  window.addEventListener('resize', updateScale)
  window.visualViewport?.addEventListener('resize', updateScale)
  document.addEventListener('click', handleDocumentClick)
})

onUnmounted(() => {
  window.removeEventListener('resize', updateScale)
  window.visualViewport?.removeEventListener('resize', updateScale)
  document.removeEventListener('click', handleDocumentClick)
})

/** @param {MouseEvent} event */
function handleDocumentClick(event) {
  const target = event.target
  if (!(target instanceof Element)) return
  if (target.closest('.xuanzeyu') || target.closest('.language-menu')) return
  languageMenuVisible.value = false
}
</script>

